package com.example.editor.textual.interaction;

import java.util.*;
import com.example.editor.grammar.core.TextPosition;
import com.example.editor.grammar.diagnostic.SourceTextIndex;
import com.example.editor.textual.source.*;
import com.example.editor.validation.model.*;

/** Índice inmutable compartido por todas las capacidades de edición textual de una revisión. */
public final class TextualWorkspaceIndex {
    private final long revision;private final List<TextualModelSourceDocument> documents;private final CanonicalModelDocument model;private final List<TextualSemanticSourceMapEntry> sourceMap;private final Map<String,TextualModelSourceDocument> documentsById;private final Map<String,CanonicalModelElement> elementsById;private final Map<String,List<TextualSemanticSourceMapEntry>> entriesBySemanticId;private final Map<String,List<TextualSemanticSourceMapEntry>> entriesByDocument;private final TextualSemanticSourceMap indexedSourceMap;
    /** Descripción: Construye un snapshot indexado sin copiar estado mutable del runtime. Entradas: revision, documents, model y sourceMap. Salida: deja el índice listo para consultas deterministas. */ public TextualWorkspaceIndex(long revision,List<TextualModelSourceDocument>documents,CanonicalModelDocument model,List<TextualSemanticSourceMapEntry>sourceMap){this.revision=Math.max(0,revision);this.documents=documents==null?List.of():List.copyOf(documents);this.model=model;this.sourceMap=sourceMap==null?List.of():List.copyOf(sourceMap);Map<String,TextualModelSourceDocument>d=new LinkedHashMap<>();for(var doc:this.documents)d.put(doc.id(),doc);documentsById=Map.copyOf(d);Map<String,CanonicalModelElement>e=new LinkedHashMap<>();if(model!=null)for(var element:model.elements())e.put(element.id(),element);elementsById=Map.copyOf(e);Map<String,List<TextualSemanticSourceMapEntry>>s=new LinkedHashMap<>(),byDoc=new LinkedHashMap<>();for(var entry:this.sourceMap){s.computeIfAbsent(entry.semanticId(),ignored->new ArrayList<>()).add(entry);byDoc.computeIfAbsent(entry.documentId(),ignored->new ArrayList<>()).add(entry);}s.replaceAll((k,v)->List.copyOf(v));byDoc.replaceAll((k,v)->List.copyOf(v));entriesBySemanticId=Map.copyOf(s);entriesByDocument=Map.copyOf(byDoc);indexedSourceMap=new TextualSemanticSourceMap(this.sourceMap);}
    /** Descripción: Obtiene la revisión del snapshot. Entradas: no requiere parámetros. Salida: devuelve la revisión inmutable. */ public long revision(){return revision;}
    /** Descripción: Obtiene los documentos del snapshot. Entradas: no requiere parámetros. Salida: devuelve una lista inmutable. */ public List<TextualModelSourceDocument>documents(){return documents;}
    /** Descripción: Obtiene el modelo canónico asociado. Entradas: no requiere parámetros. Salida: devuelve el modelo o null si todavía no existe last-known-good. */ public CanonicalModelDocument model(){return model;}
    /** Descripción: Obtiene el source map completo del snapshot. Entradas: no requiere parámetros. Salida: devuelve entradas inmutables. */ public List<TextualSemanticSourceMapEntry>sourceMap(){return sourceMap;}
    /** Descripción: Localiza un documento por identidad. Entradas: documentId: identificador del documento. Salida: devuelve Optional con el documento cuando existe. */ public Optional<TextualModelSourceDocument>document(String documentId){return Optional.ofNullable(documentsById.get(documentId));}
    /** Descripción: Localiza un elemento canónico por identidad. Entradas: semanticId: identificador semántico. Salida: devuelve Optional con el elemento cuando existe. */ public Optional<CanonicalModelElement>element(String semanticId){return Optional.ofNullable(elementsById.get(semanticId));}
    /** Descripción: Obtiene todas las entradas trazadas para una identidad. Entradas: semanticId: identificador semántico. Salida: devuelve entradas inmutables. */ public List<TextualSemanticSourceMapEntry>entries(String semanticId){return entriesBySemanticId.getOrDefault(semanticId,List.of());}
    /** Descripción: Obtiene las entradas trazadas de un documento. Entradas: documentId: identificador del documento. Salida: devuelve entradas inmutables. */ public List<TextualSemanticSourceMapEntry>documentEntries(String documentId){return entriesByDocument.getOrDefault(documentId,List.of());}
    /** Descripción: Resuelve la entrada semántica más específica bajo una posición. Entradas: documentId y position. Salida: devuelve Optional con la entrada encontrada. */ public Optional<TextualSemanticSourceMapEntry>at(String documentId,TextPosition position){return indexedSourceMap.at(documentId,position);}
    /** Descripción: Convierte una posición LSP/Monaco a offset UTF-16 del documento. Entradas: documentId y position. Salida: devuelve offset acotado. */ public int offset(String documentId,TextPosition position){var doc=documentsById.get(documentId);return doc==null?0:new SourceTextIndex(doc.content()).offset(position);}
    /** Descripción: Obtiene el índice de texto de un documento existente. Entradas: documentId. Salida: devuelve un índice nuevo sobre contenido inmutable. */ public SourceTextIndex textIndex(String documentId){var doc=documentsById.get(documentId);if(doc==null)throw new IllegalArgumentException("Unknown textual document: "+documentId);return new SourceTextIndex(doc.content());}
    /** Descripción: Obtiene relaciones canónicas o una colección vacía si no hay last-known-good. Entradas: no requiere parámetros. Salida: devuelve relaciones inmutables. */ public List<CanonicalModelRelation>relations(){return model==null?List.of():model.relations();}
    /** Descripción: Obtiene elementos canónicos o una colección vacía si no hay last-known-good. Entradas: no requiere parámetros. Salida: devuelve elementos inmutables. */ public List<CanonicalModelElement>elements(){return model==null?List.of():model.elements();}
}
